package panelarr.mihonsource.auth

import kotlinx.serialization.Serializable
import panelarr.mihonsource.storage.JsonFile
import java.nio.file.Path
import java.time.Instant

/**
 * The single admin token. It comes from the environment when set. Otherwise one is
 * generated on first start; only its hash is stored, and the token itself is handed to
 * the caller once so it can be shown to the operator.
 */
class AdminToken private constructor(
    private val hash: String,
    /** The plain token, only when it was generated by this start. */
    val generated: String?,
) {
    fun matches(token: String): Boolean = Secrets.matches(token, hash)

    @Serializable
    private data class Stored(
        val hash: String,
        val createdAt: String,
    )

    companion object {
        const val PREFIX = "msa_"

        fun load(
            authDir: Path,
            fromEnv: String?,
        ): AdminToken {
            if (fromEnv != null) return AdminToken(Secrets.hash(fromEnv), generated = null)
            val file = JsonFile(authDir.resolve("admin-token.json"), Stored.serializer(), private = true)
            file.read()?.let { return AdminToken(it.hash, generated = null) }
            val token = Secrets.randomToken(PREFIX)
            file.write(Stored(Secrets.hash(token), Instant.now().toString()))
            return AdminToken(Secrets.hash(token), generated = token)
        }
    }
}
